NAME = 'NlCanisius1939: Petrus Canisius Translation'
BOOK = 'Mark'

CHAPTERS = {
    1: {
        1: 'Aanvang der blijde boodschap van Jesus Christus, den Zoon van God:',
        2: 'zoals geschreven staat bij den profeet Isaias: Zie, Ik zend mijn gezant voor U uit, Om voor U de weg te bereiden.',
        3: 'De stem van een roepende in de woestijn: Bereidt de weg des Heren, Maakt recht zijn paden.',
        4: 'Johannes de Doper trad op in de woestijn, en preekte een doopsel van boetvaardigheid tot vergiffenis der zonden.',
        5: 'En het hele land van Judea en allen uit Jerusalem liepen naar hem uit, en lieten zich door hem dopen in de rivier de Jordaan, terwijl ze hun zonden beleden.',
        6: 'Johannes droeg een kemelharen mantel, en een leren heupkleed om zijn lenden; hij at sprinkhanen en wilde honing. En hij preekte aldus:',
        7: 'Na mij komt er Een, die machtiger is dan ik; ik ben niet waardig, om mij voor Hem neer te bukken, en zijn schoenriem los te maken.',
        8: 'Ik heb u met water gedoopt, maar Hij zal u dopen met den Heiligen Geest.',
        9: 'In die dagen kwam Jesus uit Názaret van Galilea, en werd in de Jordaan door Johannes gedoopt.',
        10: 'Maar onmiddellijk steeg Hij uit het water op, en zag de Hemel geopend, en den Geest op Zich neerdalen als een duif.',
        11: 'En er kwam een stem uit de hemel: Gij zijt mijn welbeminde Zoon, in U heb Ik welbehagen.',
        12: 'Dadelijk daarna dreef de Geest Hem naar de woestijn.',
        13: 'Veertig dagen bleef Hij in de woestijn, waar Hij door de satan werd bekoord; Hij vertoefde onder de wilde dieren, en de engelen dienden Hem.',
        14: 'Nadat Johannes was gevangen gezet, kwam Jesus in Galilea, en verkondigde het Evangelie van het koninkrijk Gods.',
        15: 'Hij zeide: De tijd is vervuld, en het koninkrijk Gods is nabij; bekeert u, en gelooft in het evangelie.',
        16: 'Toen Hij eens langs het meer van Galilea ging, zag Hij Simon en Andreas, den broer van Simon, het net uitwerpen in het meer; want ze waren vissers.',
        17: 'En Jesus sprak tot hen: Volgt Mij; Ik zal mensenvissers van u maken.',
        18: 'Aanstonds verlieten ze de netten, en volgden Hem.',
        19: 'Een weinig verder zag Hij Jakobus, den zoon van Zebedeüs, en Johannes zijn broer, die ook in een boot waren en de netten herstelden.',
        20: 'Aanstonds riep Hij ze. En ze lieten hun vader Zebedeüs in de boot met de bemanning achter, en volgden Hem.',
        21: 'Zij begaven zich nu naar Kafárnaum. En terstond ging Hij op de sabbat de synagoge binnen, en trad als leraar op.',
        22: 'Men stond verbaasd over zijn leer; want Hij leerde hen als een die gezag heeft, en niet zoals de schriftgeleerden.',
        23: 'Al heel spoedig was er in hun synagoge een man met een onreinen geest. Hij riep:',
        24: 'Wat hebt Gij met ons te maken, Jesus van Názaret? Zijt Gij gekomen, om ons in het verderf te storten? Ik weet, wie Gij zijt: de Heilige Gods.',
        25: 'Maar Jesus gebood hem: Zwijg, en ga van hem uit.',
        26: 'En onder stuiptrekken en luid geschreeuw ging de onreine geest van hem uit.',
        27: 'Allen waren verbaasd, en vroegen zich af: Wat kan dat toch zijn? Een nieuwe leer met gezag! Bovendien gebiedt Hij de onreine geesten, en ze gehoorzamen Hem!',
        28: 'En zijn faam ging aanstonds overal rond door heel het land van Galilea.',
        29: 'Toen zij de synagoge hadden verlaten, begaven zij zich, van Jakobus en Johannes vergezeld, rechtstreeks naar het huis van Simon en Andreas.',
        30: 'De schoonmoeder van Simon lag ziek aan de koorts; en aanstonds vertelden ze het Hem.',
        31: 'Hij trad nader, vatte haar bij de hand, en richtte haar op; de koorts verliet haar, en ze bediende Hem.',
        32: 'Toen het avond was geworden en de zon was ondergegaan, bracht men alle zieken en bezetenen naar Hem toe;',
        33: 'de hele stad stond voor de deur bijeen.',
        34: 'En Hij genas er velen, die aan verschillende kwalen leden. Ook dreef Hij veel duivels uit; maar Hij liet niet toe, dat de duivels zeiden, dat ze Hem kenden.',
        35: 'Zeer vroeg in de morgen stond Hij op, en ging heen; Hij begaf zich naar een eenzame plaats, om er te bidden.',
        36: 'Simon en zijn gezellen gingen Hem achterna,',
        37: 'vonden Hem, en zeiden: Iedereen zoekt U.',
        38: 'Maar Hij sprak tot hen: Laten we naar de omliggende dorpen gaan, om ook daar te preken; want daartoe ben Ik gekomen.',
        39: 'Zo trok Hij heel Galilea rond: Hij preekte in hun synagogen, en dreef de duivels uit.',
        40: 'Eens kwam een melaatse naar Hem toe, die smekend voor Hem op de knieën viel, en tot Hem sprak: Zo Gij wilt, kunt Gij me reinigen.',
        41: 'Jesus had medelijden met hem: Hij strekte zijn hand uit, raakte hem aan, en zeide tot hem: Ik wil, word gereinigd!',
        42: 'Terstond verdween de melaatsheid; hij was gereinigd.',
        43: 'Onmiddellijk zond Hij hem weg, vermaande hem ernstig.',
        44: 'en zei hem: Pas op, dat ge het niemand zegt; maar ga heen, vertoon u aan den priester, en offer voor uw reiniging wat Moses als bewijs voor hen heeft voorgeschreven.',
        45: 'Maar nauwelijks was hij heengegaan, of hij begon het overal te vertellen, en het geval ruchtbaar te maken; zodat Jesus niet meer openlijk in een stad kon komen, maar buiten op eenzame plaatsen vertoefde. Toch kwam men van alle kanten naar Hem toe.',
    },
    2: {
        1: 'Na enige tijd kwam Hij weer te Kafárnaum terug.',
        2: 'Toen men hoorde, dat Hij binnenshuis was, kwamen er aanstonds zo velen bijeen, dat er geen plaats genoeg was, zelfs niet aan de deur. En Hij preekte hun het woord.',
        3: 'Nu kwam men Hem een lamme brengen, die door vier man gedragen werd.',
        4: 'Daar ze hem wegens de menigte niet bij Hem konden brengen, maakten ze een opening in het dak, waar Hij was; en toen ze het hadden opengebroken, lieten ze het bed, waarop de lamme lag, naar beneden.',
        5: 'Toen Jesus hun geloof zag, sprak Hij tot den lamme: Mijn zoon, uw zonden zijn u vergeven.',
        6: 'Nu zaten er enige schriftgeleerden bij, die bij zichzelf dachten:',
        7: 'Hoe kan Hij zó spreken? Hij lastert God! Wie kan zonden vergeven, dan God alleen?',
        8: 'Aanstonds doorzag Jesus in zijn geest, dat ze zo bij zichzelf dachten; en Hij sprak tot hen: Waarom denkt ge dit bij uzelf?',
        9: 'Wat is gemakkelijker, tot den lamme te zeggen: uw zonden worden u vergeven, of te zeggen: sta op, neem uw bed, en ga heen.',
        10: 'Welnu, opdat ge weten moogt, dat de Mensenzoon macht heeft op aarde, om zonden te vergeven, (hier sprak hij tot den lamme:)',
        11: 'Ik zeg u: sta op, neem uw bed, en ga naar huis.',
        12: 'Onmiddellijk stond hij op, nam zijn bed, en ging heen ten aanschouwen van allen, zodat allen verbaasd waren, God loofden, en zeiden: Nooit hebben we zo iets gezien.',
        13: 'Weer ging Hij uit naar het meer, en heel de menigte kwam naar Hem toe; en Hij onderrichtte ze.',
        14: 'In het voorbijgaan zag Hij Levi, den zoon van Alfeus, aan het tolhuis zitten; en Hij zei hem: Volg Mij! Hij stond op, en volgde Hem.',
        15: 'Toen Hij eens in diens huis aan tafel was, lagen ook vele tollenaars en zondaars met Jesus en zijn leerlingen aan; want velen waren Hem gevolgd.',
        16: 'De schriftgeleerden en farizeën zagen dus, dat Hij met de tollenaars en zondaars at, en zeiden tot zijn leerlingen: Waarom eet Hij met tollenaars en zondaars?',
        17: 'Jesus hoorde het, en sprak tot hen: De gezonden hebben geen geneesheer nodig, wel de zieken. Ik ben niet gekomen, om rechtvaardigen, maar om zondaars te roepen.',
        18: 'De leerlingen van Johannes en de farizeën hadden eens een vastendag. En men kwam naar Hem toe, en zeide Hem: Waarom vasten de leerlingen van Johannes en van de farizeën, en vasten uw leerlingen niet?',
        19: 'Jesus sprak tot hen: Kunnen de bruiloftsgasten vasten, zolang de bruidegom bij hen is? Zolang ze den bruidegom bij zich hebben, kunnen ze niet vasten.',
        20: 'Maar de dagen zullen komen, dat de bruidegom van hen wordt weggenomen; op die dag zullen ze vasten.',
        21: 'Niemand zet een lap ongekrompen laken op een oud kleed; anders scheurt het nieuwe stuk van het oude af, en er ontstaat nog groter scheur.',
        22: 'Ook giet niemand nieuwe wijn in oude zakken; anders doet de wijn de zakken bersten en de wijn loopt weg; neen, nieuwe wijn in nieuwe zakken!',
        23: 'Eens ging Hij op de sabbat door het korenveld, en zijn leerlingen begonnen, al voortwandelend, aren te plukken.',
        24: 'En de farizeën zeiden Hem: Zie, waarom doen ze op de sabbat wat niet is geoorloofd?',
        25: 'Hij sprak tot hen: Hebt ge nooit gelezen, wat David deed, toen hij in nood was met zijn gevolg, en honger had?',
        26: 'Hoe hij onder den hogepriester Abjatár het huis van God binnenging, en de toonbroden opat, die alleen de priesters mogen eten: en hoe hij er ook van gaf aan hen, die bij hem waren?',
        27: 'En Hij vervolgde tot hen: De sabbat is om den mens gemaakt, en niet de mens om de sabbat.',
        28: 'De Mensenzoon is dus ook heer van de sabbat.',
    },
    3: {
        1: 'Eens ging Hij weer een synagoge binnen; daar was een man wiens hand verdord was.',
        2: 'En ze bespiedden Hem, of Hij hem ook op de sabbat zou genezen, om Hem dan te kunnen beschuldigen.',
        3: 'En Hij zei tot den man met de verdorde hand: Kom hier in het midden!',
        4: 'Toen sprak Hij tot hen: Mag men op de sabbat goed doen of kwaad, iemand redden of doden? Ze zwegen.',
        5: 'Toornig liet Hij zijn blik over hen rondgaan, bedroefd over de verblinding van hun hart; en Hij sprak tot den man: Strek uw hand uit! Hij strekte ze uit, en zijn hand was genezen.',
        6: 'Toen gingen de farizeën heen, en spanden terstond met de herodianen tegen Hem samen, om Hem ten val te',
        7: 'Nu ging Jesus met zijn leerlingen terug naar het meer, en een talrijke schare uit Galilea volgde Hem. Ook uit Judea,',
        8: 'Jerusalem, Idumea, het Overjordaanse en uit de streek van Tyrus en Sidon kwam men in grote menigte naar Hem toe, toen men hoorde, al wat Hij deed.',
        9: 'En Hij beval zijn leerlingen, een boot voor Hem gereed te houden met het oog op de schare, opdat ze Hem niet zouden dringen.',
        10: 'Want Hij genas er velen; zodat allen, die kwalen hadden, op Hem aandrongen, om Hem aan te raken.',
        11: 'En als de onreine geesten Hem zagen, vielen ze voor Hem neer, en schreeuwden het uit:',
        12: 'Gij zijt de Zoon van God. Maar Hij verbood hun streng, Hem bekend te maken.',
        13: 'Vervolgens besteeg Hij de berg en riep hen, die Hij zelf wilde; en ze kwamen bij Hem.',
        14: 'En twaalf stelde Hij er aan, om bij Hem te blijven, en om hen ter prediking uit te zenden,',
        15: 'met de macht om duivels uit te drijven.',
        16: 'Deze twaalf stelde Hij aan: Simon, dien Hij de bijnaam Petrus gaf;',
        17: 'dan Jakobus, den zoon van Zebedeus, en Johannes, den broer van Jakobus, aan wie Hij de bijnaam Boanerges gaf, dat is zonen van de donder.',
        18: 'Verder Andreas en Filippus, Bartolomeus en Matteüs, Tomas en Jakobus, den zoon van Alfeus, Taddeus en Simon den Kananeër,',
        19: 'en Judas Iskáriot, die Hem heeft verraden.',
        20: 'Daarop ging Hij naar huis: maar weer liep de menigte samen, zodat zij niet eens konden eten.',
        21: 'Toen zijn verwanten dit hoorden, trokken ze er op af, om Hem vast te houden; want ze zeiden: Hij is krankzinnig.',
        22: 'Maar de schriftgeleerden, die van Jerusalem waren gekomen, zeiden: Hij is van Beélzebub bezeten, en door den vorst der duivels drijft Hij de duivels uit.',
        23: 'Hij riep hen tot Zich, en sprak hen in gelijkenissen toe: Hoe kan een satan den satan verdrijven?',
        24: 'Wanneer een rijk inwendig is verdeeld, dan kan dat rijk niet in stand blijven.',
        25: 'En wanneer een huis inwendig is verdeeld, dan zal dat huis geen stand kunnen houden.',
        26: 'Wanneer dus de satan in opstand komt tegen zichzelf, en verdeeld is, dan kan hij geen stand houden, maar het loopt met hem af.',
        27: 'Niemand toch kan het huis van een sterken man binnendringen en zijn huisraad roven, als hij niet eerst den sterke bindt; eerst dan zal hij zijn huis kunnen plunderen.',
        28: 'Voorwaar, Ik zeg u: Alle zonden zullen aan de mensenkinderen worden vergeven: zelfs alle godslasteringen, die ze hebben geuit.',
        29: 'Maar wie lastert tegen den Heiligen Geest, krijgt in eeuwigheid geen vergiffenis, maar hij is schuldig aan een eeuwige zonde.',
        30: 'Ze hadden immers gezegd: Hij heeft een onreinen geest.',
        31: 'Toen kwamen zijn moeder en broeders; ze bleven buiten staan en lieten Hem roepen.',
        32: 'Maar er zat een menigte om Hem heen: men zei Hem dus: Zie, uw moeder, uw broeders en zusters staan buiten, en zoeken U.',
        33: 'Maar Hij gaf hun ten antwoord: Wie is mijn moeder, en wie zijn mijn broeders?',
        34: 'En terwijl Hij rondkeek naar hen, die in een kring om Hem heen waren gezeten, sprak Hij: Ziedaar mijn moeder en broeders!',
        35: 'Wie de wil van God volbrengt, hij is mijn broeder en zuster en moeder.',
    },
    4: {
        1: 'Weer ging Hij onderricht geven aan het meer. En een grote menigte verzamelde zich om Hem heen, zodat Hij een boot in ging, en daar neerzat op het meer, terwijl heel de menigte langs het meer aan de oever bleef staan.',
        2: 'En Hij leerde hun vele dingen in gelijkenissen, en onderrichtte hen aldus:',
        3: 'Luistert! Zie, de zaaier ging uit om te zaaien.',
        4: 'En onder het zaaien viel een gedeelte langs de weg; en de vogels uit de lucht kwamen, en pikten het op.',
        5: 'Een ander gedeelte viel op de steengrond, waar het niet veel aarde had. Aanstonds kwam het op, omdat het geen diepe aarde had;',
        6: 'maar toen de zon was opgegaan, werd het verschroeid en verdorde, daar het geen wortel geschoten had.',
        7: 'Weer een ander gedeelte viel tussen de doornen; de doornen schoten op, en verstikten het; en het droeg geen vrucht.',
        8: 'Een ander gedeelte viel in de goede aarde; het schoot op, groeide aan, en droeg vrucht; het één bracht dertig- het ander zestig- en het ander honderdvoud op.',
        9: 'En Hij sprak: Wie oren heeft om te horen, hij hore!',
        10: 'Maar toen Hij alleen was, vroegen Hem de twaalf, en zij die bij Hem waren, naar de zin der gelijkenis.',
        11: 'En Hij sprak tot hen: U is het geheim van het koninkrijk Gods toevertrouwd; maar zij, die buiten staan, ontvangen alles in parabels:',
        12: 'Opdat ze scherp zouden zien, en niet inzien, Scherp zouden horen, en niet verstaan; Opdat ze zich niet zouden bekeren, En vergiffenis zouden bekomen.',
        13: 'En Hij zeide hun: Verstaat gij deze gelijkenis niet? Hoe zult gij dan al de andere parabels verstaan?',
        14: 'De zaaier, hij zaait het woord.',
        15: 'Dit zijn de lieden langs de weg, waar het woord wordt gezaaid: wanneer ze het hebben gehoord, komt aanstonds de satan en rooft het woord, dat in hen was gezaaid.',
        16: 'Zo ook zij, die op de steengrond worden gezaaid: dat zijn zij, die terstond met vreugde het woord aanvaarden, zodra ze het horen;',
        17: 'ze hebben echter geen wortel geschoten, maar zijn onstandvastig; en als er later verdrukking en vervolging ontstaat om wille van het woord, dan zijn ze aanstonds geërgerd.',
        18: 'Anderen zijn er, die tussen de doornen worden gezaaid: dat zijn zij, die wel luisteren naar het woord:',
        19: 'maar de beslommering van de wereld, de verleiding van de rijkdom en de begeerten naar andere dingen vallen er tussen, en verstikken het woord: het blijft zonder vrucht.',
        20: 'En die op de goede aarde werden gezaaid, zijn allen, die het woord vernemen, het aanvaarden, en het vrucht laten dragen; het éne dertig- het andere zestig- en het andere honderdvoud.',
        21: 'Weer sprak Hij tot hen: Haalt men soms de lamp, om ze onder de korenmaat te zetten of onder het bed? Is het niet, om ze op de kandelaar te plaatsen?',
        22: 'Want niets is verborgen, of het moet worden geopenbaard; en niets is geheim, of het komt aan het licht.',
        23: 'Zo iemand oren heeft om te horen, hij hore!',
        24: 'Nog zeide Hij hun: Let op, wat gij hoort. Met de maat, waarmee gij meet, zal u worden toegemeten, met een toemaat bovendien.',
        25: 'Want wie heeft, hem zal gegeven worden; en wie niet heeft, hem zal ook nog ontnomen worden, wat hij bezit.',
        26: 'Weer zeide Hij: Het gaat met het koninkrijk Gods als met een mens, die het zaad in de aarde werpt;',
        27: 'dan gaat hij slapen des nachts, en staat op overdag. En het zaad ontkiemt en groeit op; zelf weet hij niet, hoe.',
        28: 'Want vanzelf brengt de aarde vruchten voort, eerst de halmen, dan de aar, daarna het volle graan in de aar.',
        29: 'En als het koren rijp is, slaat hij er aanstonds de sikkel in; want het is tijd voor de oogst.',
        30: 'Nog sprak Hij: Waarmede zullen wij het koninkrijk Gods vergelijken, of onder welke parabel het brengen?',
        31: 'Het is gelijk aan een mosterdzaadje; wanneer men het zaait in de aarde, is het ‘t kleinste van alle zaden op aarde.',
        32: 'Maar wanneer het eenmaal gezaaid is, groeit het op, en wordt groter dan alle tuingewas; het schiet grote takken, zodat de vogels in de lucht kunnen nestelen onder zijn lommer.',
        33: 'En in veel gelijkenissen van die aard sprak Hij tot hen het woord, voor zover ze het konden verstaan;',
        34: 'en zonder gelijkenis sprak Hij hen niet toe. Maar alleen aan zijn leerlingen legde Hij alles uit.',
        35: 'Tot hen sprak Hij nog op diezelfde dag, toen het reeds laat was geworden: Laat ons oversteken naar de andere kant.',
        36: 'Toen lieten ze de menigte gaan, en namen Hem mee, daar Hij reeds in de boot was; ook andere boten waren er bij.',
        37: 'En een hevige storm brak los, en de golven sloegen over de boot, zodat ze vol water kwam.',
        38: 'Hij zelf lag aan de achtersteven op een kussen te slapen. Ze maakten Hem wakker, en zeiden tot Hem: Meester, raakt het U niet, dat wij vergaan?',
        39: 'Nu stond Hij op, gebood aan de wind, en sprak tot het meer: Zwijg, wees stil! De wind ging liggen, en het werd heel stil.',
        40: 'Toen sprak Hij tot hen: Wat zijt gij bevreesd? Hebt gij nog geen geloof? Maar een hevige angst greep hen aan, en ze zeiden tot elkander: Wie is Hij toch, dat zelfs de wind en het meer Hem gehoorzamen?',
    },
    5: {
        1: 'Zo kwamen zij aan de overkant van het meer in het land der Gerasenen.',
        2: 'Zodra Hij het schip verliet, kwam Hem uit de grafspelonken een man tegemoet, die door een onreinen geest was bezeten.',
        3: 'Hij had zijn verblijf in de graven, en niemand kon hem zelfs met ketens meer binden;',
        4: 'meermalen reeds was hij met voetboeien en ketens gebonden, maar hij had de ketens stuk getrokken en de voetboeien verbroken. Niemand was in staat hem te temmen.',
        5: 'Dag en nacht was hij in de grafspelonken en op de bergen, waar hij schreeuwde, en zich met stenen sloeg.',
        6: 'Toen hij van verre Jesus zag, snelde hij toe, viel voor Hem neer,',
        7: 'en schreeuwde het uit: Wat hebt Gij met ons te maken, Jesus, Zoon van den Allerhoogsten God? Ik bezweer U bij God, mij niet te gaan kwellen.',
        8: 'Want Hij had hem gezegd: Onreine geest, ga uit van dien man!',
        9: 'Nu vroeg Hij hem: Hoe is uw naam? En hij zei Hem: Legioen is mijn naam, want we zijn velen.',
        10: 'En hij bad Hem dringend, hem toch niet buiten die streek te bannen.',
        11: 'Nu liep daar bij de berg een grote troep zwijnen te grazen.',
        12: 'Ze smeekten Hem, en zeiden: Zend ons naar de zwijnen, opdat we daar ingaan.',
        13: 'Hij stond het hun toe. Toen gingen de onreine geesten uit, en wierpen zich op de zwijnen. En de troep van ongeveer twee duizend plofte van de steilte in het meer, en verdronk in het meer.',
        14: 'De drijvers vluchtten heen, en vertelden het in stad en land. Men kwam dus zien, wat er gebeurd was.',
        15: 'Toen ze nu bij Jesus kwamen, en den bezetene zagen zitten, gekleed en goed bij verstand, ofschoon hij door het legioen was bezeten geweest, werden ze bevreesd.',
        16: 'En zij, die het gezien hadden, verhaalden hun wat er met den bezetene was gebeurd, en ook met de zwijnen.',
        17: 'Toen verzochten ze Hem, om heen te gaan uit hun gebied.',
        18: 'Toen Hij zich nu in de boot begaf, vroeg de gewezen bezetene verlof, bij Hem te blijven.',
        19: 'Hij stond het niet toe, maar zei hem: Ga naar huis, naar de uwen, en meld hun alwat de Heer u gedaan heeft, en hoe Hij Zich over u heeft ontfermd.',
        20: 'Hij ging heen, en begon te verkondigen in de Dekápolis, wat Jesus hem had gedaan; en allen stonden verbaasd.',
        21: 'Toen Jesus in de boot weer de overkant had bereikt, verzamelde zich een grote menigte om Hem heen. En terwijl Hij Zich aan de oever van het meer bevond.',
        22: 'kwam daar een van de oversten der synagoge, Jaïrus genaamd. Toen hij Hem zag, viel hij aan zijn voeten neer,',
        23: 'en bad Hem met aandrang: Mijn dochtertje ligt te sterven. Kom, en leg haar de handen op: dan zal ze worden gered, en blijven leven.',
        24: 'Hij ging met hem mee. Een grote menigte volgde Hem, en drong tegen Hem op.',
        25: 'Nu was daar een vrouw, die twaalf jaren lang aan bloedvloeiing leed.',
        26: 'Veel had ze van verschillende geneesheren moeten verduren; al wat ze bezat, had ze ten koste gelegd, maar heel geen baat gevonden; ze was eer nog erger geworden.',
        27: 'Daar ze van Jesus had gehoord, trad ze onder de menigte achter Hem aan, en raakte zijn kleed aan.',
        28: 'Want ze dacht: Als ik alleen maar zijn kleren aanraak, zal ik genezen.',
        29: 'En terstond droogde haar bloedvloeiing op, en gevoelde ze aan haar lichaam, dat ze van haar kwaal was genezen.',
        30: 'Jesus was Zich bewust van de kracht, die er van Hem was uitgegaan; aanstonds keerde Hij Zich onder de menigte om, en sprak: Wie heeft mijn kleren aangeraakt?',
        31: 'Zijn leerlingen zeiden tot Hem: Gij ziet, dat de menigte op U aandringt, en Gij vraagt: Wie heeft Mij aangeraakt?',
        32: 'Maar Hij keek rond, om te zien, wie het gedaan had.',
        33: 'Angstig en bevend kwam de vrouw naderbij, daar ze wist, wat er met haar was gebeurd; ze viel voor Hem neer, en zeide Hem de volle waarheid.',
        34: 'Maar Hij sprak tot haar: Dochter, uw geloof heeft u gered; ga in vrede, en wees genezen van uw kwaal.',
        35: 'Terwijl Hij nog sprak. kwamen er lieden van den overste der synagoge, en zeiden: Uw dochter is gestorven; waarom den Meester nog lastig gevallen?',
        36: 'Jesus hoorde wat er gezegd werd, en sprak tot den overste: Vrees niet, maar geloof!',
        37: 'Hij liet niemand met Zich meegaan dan Petrus, Jakobus en Johannes, den broer van Jakobus.',
        38: 'Toen zij bij het huis van den overste waren gekomen, zag Hij daar het rouwmisbaar en de wenende en luid jammerende mensen.',
        39: 'Hij ging binnen, en zeide tot hen: Wat tiert gij, en weent gij? Het kind is niet dood, maar het slaapt.',
        40: 'Ze lachten Hem uit. Nadat Hij ze allen had buiten gezet, nam Hij den vader en de moeder van het kind en zijn metgezellen met Zich mee, en ging het vertrek binnen, waar het kind lag.',
        41: 'Hij vatte het kind bij de hand, en sprak tot haar: Talita koemi: wat betekent: Meisje, Ik zeg u, sta op!',
        42: 'Onmiddellijk stond het meisje op, en liep heen en weer: want het was twaalf jaar oud. En ze stonden verstomd van verbazing.',
        43: 'Maar Hij gebood hun ten strengste, het niemand te laten weten. Ook zeide Hij nog, dat men haar te eten zou geven.',
    },
    6: {
        1: 'Hij vertrok van daar, en ging naar zijn vaderstad; en zijn leerlingen volgden Hem.',
        2: 'En op de sabbat begon Hij in de synagoge te leren. De vele toehoorders stonden verbaasd, en ze zeiden: Waar heeft Hij dit alles vandaan? Wat is dit voor wijsheid, die Hem is gegeven; en wat zijn het voor wonderen, die door zijn handen gebeuren?',
        3: 'Is Hij niet de timmerman, de zoon van Maria, de broer van Jakobus en Josef, Judas en Simon; en leven zijn zusters niet hier onder ons? En ze ergerden zich aan Hem.',
        4: 'Maar Jesus zeide tot hen: Een profeet wordt enkel in zijn vaderland miskend, onder zijn verwanten en in zijn familie.',
        5: 'Hij kon daar geen wonder verrichten, behalve enkele zieken genezen, door ze de handen op te leggen.',
        6: 'En Hij verwonderde Zich over hun ongeloof. Nu trok Hij de dorpen in de omtrek al lerende rond.',
        7: 'Ook riep Hij het twaalftal bij Zich, zond ze twee aan twee uit, en gaf hun de macht over de onreine geesten.',
        8: 'Hij gebood hun, niets mee te nemen op weg, dan alleen een staf; geen reiszak, geen brood, geen geld in de gordel;',
        9: 'ze mochten wel sandalen dragen, maar geen dubbele onderkleding.',
        10: 'En Hij sprak tot hen: Wanneer gij een huis zijt binnengegaan. blijft dan daar, totdat gij weer afreist.',
        11: 'En waar men u niet ontvangt en niet naar u luistert, gaat daar vandaan, en schudt het stof van uw voeten, als een getuigenis tegen hen.',
        12: 'Ze gingen heen, en preekten, dat men zich zou bekeren.',
        13: 'Ze dreven vele duivels uit, zalfden vele zieken met olie, en genazen ze.',
        14: 'Ook koning Herodes hoorde van Hem: want zijn naam werd beroemd. Men zeide: Johannes de Doper is van de doden opgestaan; daarom werken die krachten in Hem.',
        15: 'Anderen zeiden: Het is Elias. Anderen weer: Hij is een gewone profeet.',
        16: 'Maar toen Herodes het hoorde, zeide hij: Het is Johannes, dien ik onthoofd heb; hij is verrezen.',
        17: 'Herodes namelijk had Johannes laten grijpen, in boeien geslagen en in de gevangenis geworpen, naar aanleiding van Heródias, de vrouw van zijn broer Filippus, omdat hij haar had gehuwd.',
        18: 'Want Johannes had tot Herodes gezegd: Ge moogt de vrouw van uw broer niet hebben.',
        19: 'Heródias was hem dus vijandig gezind, en wilde hem doden; maar het lukte haar niet.',
        20: 'Want Herodes had ontzag voor Johannes, daar hij wist, dat hij een rechtvaardig en heilig man was; en hij beschermde hem. Telkens wanneer hij hem hoorde, raakte hij in grote verlegenheid; toch luisterde hij gaarne naar hem.',
        21: 'Maar er kwam een gunstige dag, toen Herodes op zijn verjaringsfeest een maaltijd gaf aan zijn groten en legeroversten en de aanzienlijken van Galilea.',
        22: 'Nu kwam de dochter van die Heródias binnen, en danste; en ze behaagde aan Herodes en aan de gasten. Toen sprak de koning tot het meisje: Vraag van mij wat ge wilt, en ik zal het u geven.',
        23: 'En hij zwoer haar: Wat ge ook vraagt, ik zal het u geven, al was het ook de helft van mijn rijk.',
        24: 'Ze ging heen. en zei tot haar moeder: Wat zal ik vragen? Deze sprak: Het hoofd van Johannes den Doper.',
        25: 'Aanstonds spoedde ze zich naar den koning, en eiste: Ik verlang, dat ge me op staande voet op een schotel het hoofd van Johannes den Doper geeft.',
        26: 'Wel had de koning er spijt van, maar om de eed en om de gasten wilde hij haar niet teleurstellen.',
        27: 'Onmiddellijk stuurde hij een der trawanten. en gaf bevel, het hoofd van Johannes te brengen. Deze ging heen, en onthoofdde hem in de gevangenis.',
        28: 'Hij bracht het hoofd op een schotel, en gaf het aan het meisje; en het meisje gaf het aan haar moeder.',
        29: 'Toen zijn leerlingen dit hadden gehoord, kwamen ze zijn lichaam halen, en legden het in een graf.',
        30: 'Toen de apostelen te zamen bij Jesus waren teruggekeerd, verhaalden ze Hem al wat ze hadden gedaan en geleerd.',
        31: 'En Hij zeide tot hen: Komt nu met Mij mee naar een eenzame plaats, en rust wat uit. Want velen liepen in en uit, zodat ze zelfs geen tijd hadden om te eten.',
        32: 'Geheel alleen vertrokken ze dus in de boot naar een eenzame plaats.',
        33: 'Maar velen zagen hen vertrekken, en begrepen waarheen; uit alle steden liep men gezamenlijk te voet daar naar toe, en men was er nog eerder dan zij.',
        34: 'Toen Jesus uitsteeg, zag Hij dus een talrijke schare. Hij had medelijden met hen, daar ze als schapen zonder herder waren; en Hij begon ze velerlei dingen te leren.',
        35: 'Toen het reeds laat was geworden, kwamen zijn leerlingen naar Hem toe, en zeiden: Deze plaats is woest, en het is reeds laat geworden;',
        36: 'stuur ze weg, dan kunnen ze naar de omliggende dorpen en gehuchten gaan, om zich levensmiddelen te kopen.',
        37: 'Maar Hij gaf hun ten antwoord: Geeft gij hun te eten! Ze zeiden Hem: Zullen we dan voor tweehonderd tienlingen brood gaan kopen, en hun te eten geven?',
        38: 'Maar Hij sprak tot hen: Hoeveel broden hebt gij? Gaat eens zien. En na gedaan onderzoek zeiden ze: Vijf, en twee vissen.',
        39: 'Nu gebood Hij hun, ze allen in groepen neer te zetten op het groene gras.',
        40: 'Ze gingen zitten in groepen van honderd en groepen van vijftig.',
        41: 'Toen nam Hij de vijf broden en de twee vissen, zag op ten hemel, en sprak er de zegen over uit: Hij brak de broden en gaf ze aan zijn leerlingen, om ze hun aan te bieden: ook de twee vissen verdeelde Hij onder hen.',
        42: 'Allen aten en werden verzadigd.',
        43: 'En ze verzamelden de brokken; twaalf korven vol, behalve nog het overschot van de vissen.',
        44: 'Het waren vijf duizend mannen, die van de broden hadden gegeten.',
        45: 'Onmiddellijk daarna dwong Hij zijn leerlingen om scheep te gaan, en vóór Hem uit naar Betsáida over te steken; intussen zond Hij de schare heen.',
        46: 'En nadat Hij ze had weggezonden, ging Hij het gebergte in, om er te bidden.',
        47: 'Toen het nacht begon te worden, was de boot midden op het meer, en Hij was alleen op het land.',
        48: 'Hij zag ze tobben, om vooruit te komen; want de wind was tegen. En tegen de vierde nachtwaak kwam Hij naar hen toe, wandelend op het meer; en Hij wilde ze voorbijgaan.',
        49: 'Toen ze Hem op het meer zagen wandelen, meenden ze, dat het een spook was, en ze gilden het uit;',
        50: 'want allen zagen Hem, en waren ontsteld. Aanstonds sprak Hij hen toe, en zeide hun: Weest gerust, Ik ben het; vreest niet!',
        51: 'Hij stapte bij hen in de boot, en de wind bedaarde. Nu raakten ze heel en al van streek;',
        52: 'want ze waren door de broden niet tot inzicht gekomen, maar hun hart was blind gebleven.',
        53: 'Toen ze de overkant hadden bereikt, kwamen ze in het land Gennézaret; daar legden ze aan.',
        54: 'Nauwelijks waren ze uit de boot gegaan, of men had Hem herkend.',
        55: 'En men liep die hele landstreek af; en als men hoorde, dat Hij ergens was, begon men de zieken op hun bedden daarheen te dragen.',
        56: 'Waar Hij ook kwam, in dorpen, steden of gehuchten, daar legden ze de zieken neer op de pleinen, en baden Hem, dat ze enkel de zoom van zijn kleed mochten aanraken. En allen, die Hem aanraakten, werden genezen.',
    },
    7: {
        1: 'Toen kwamen de farizeën en sommige schriftgeleerden. die van Jerusalem waren gekomen, gezamenlijk naar Hem toe.',
        2: 'Zij zagen, dat enigen van zijn leerlingen brood aten met onreine, dat is met ongewassen handen.',
        3: 'De farizeën toch en alle Joden eten niet, zonder zich de vingertoppen te hebben gewassen, getrouw aan de overlevering der ouden;',
        4: 'en ze eten niets van de markt, zonder het eerst te besprenkelen; en vele andere dingen zijn er, die ze krachtens overlevering te onderhouden hebben, zoals het wassen van drinkbekers, kannen en koperen vaten.',
        5: 'De farizeën en de schriftgeleerden vroegen Hem dus: Waarom gedragen uw leerlingen zich niet naar de overlevering der ouden, en eten ze brood met onreine handen?',
        6: 'Hij sprak tot hen: Huichelaars; terecht heeft Isaias over u geprofeteerd, zoals er geschreven staat: Dit volk eert Mij met de lippen, maar hun hart is verre van Mij;',
        7: 'ze eren Mij tevergeefs, daar ze leerstellingen voordragen, die menselijke geboden zijn.',
        8: 'Gods gebod verwaarloost gij, maar aan de overlevering der mensen houdt gij vast.',
        9: 'Nog sprak Hij tot hen: Het staat u fraai, Gods gebod te verkrachten, om uw overlevering door te zetten.',
        10: 'Want Moses heeft gezegd: "Eer uw vader en moeder", en: "Wie vader of moeder vloekt, moet sterven."',
        11: 'Gij echter zegt: Zo iemand tot vader en moeder zegt: "Korban (dat is offergave) is alles, waarmee ik u van dienst zou kunnen zijn",',
        12: 'dan mag hij volgens u niets meer voor zijn vader of moeder doen.',
        13: 'Zo verkracht gij Gods woord door uw overlevering, die gij blijft leren. En dergelijke dingen doet gij bij hopen.',
        14: 'Hij riep de schare weer naar Zich toe, en sprak tot hen: Hoort allen naar Mij, en verstaat het goed!',
        15: 'Niets kan den mens verontreinigen, wat van buitenaf in hem binnenkomt; maar wat er uitgaat van den mens, dat verontreinigt den mens.',
        16: 'Zo iemand oren heeft om te horen, hij hore!',
        17: 'Toen Hij nu van het volk was weggegaan en thuis was gekomen, vroegen zijn leerlingen Hem naar de zin der parabel.',
        18: 'En Hij sprak tot hen: Zijt ook gij nog zonder begrip? Begrijpt gij dan niet, dat niets den mens kan verontreinigen, wat van buitenaf in hem binnenkomt?',
        19: 'Want het komt niet in zijn hart, maar in de buik, en het gaat weer uit op zekere plaats. Hij verklaarde dus alle spijzen voor rein.',
        20: 'En Hij ging voort: Wat er uitgaat van den mens, dat verontreinigt den mens.',
        21: 'Want van binnenaf, uit het hart der mensen, komen de slechte gedachten voort, ontucht, diefstal, moord,',
        22: 'echtbreuk, gierigheid, boosaardigheid, bedrog, wellust, afgunst, godslastering, hoogmoed, lichtzinnigheid.',
        23: 'Al die boze dingen komen van binnenaf, en verontreinigen den mens.',
        24: 'Toen stond Hij op, en vertrok vandaar naar de streek van Tyrus. Daar ging Hij een huis binnen, maar wilde niet, dat iemand het wist. Toch kon Hij niet verborgen blijven.',
        25: 'Want een vrouw, wier dochtertje door een onreinen geest was bezeten, kwam, zodra ze van Hem had gehoord, naar Hem toe, en wierp zich aan zijn voeten neer.',
        26: 'De vrouw was een heiden, van syrofenicische afkomst. Ze bad Hem, den duivel uit haar dochter te drijven.',
        27: 'Jesus zeide tot haar: Laat eerst de kinderen verzadigd worden; het is niet goed, het brood der kinderen te nemen, en het voor de hondjes te werpen.',
        28: 'Maar ze gaf Hem ten antwoord: Jawel, Heer: de hondjes onder de tafel eten toch ook van de kruimels der kinderen.',
        29: 'Toen sprak Hij tot haar: Om zo’n woord moogt ge gaan; de duivel heeft uw dochter verlaten.',
        30: 'Ze ging naar huis, en vond het meisje te bed liggen; de duivel was uitgegaan.',
        31: 'Toen Hij weer uit de streek van Tyrus vertrok, ging Hij over Sidon naar het meer van Galilea, midden in het gebied der Dekápolis.',
        32: 'Daar bracht men een doofstomme naar Hem toe, en smeekte Hem, dien de hand op te leggen.',
        33: 'Hij nam hem ter zijde buiten de kring van de menigte, stak de vingers in zijn oren, spuwde, en raakte zijn tong daarmee aan.',
        34: 'Hij zag op naar de hemel, slaakte een zucht, en zeide tot hem: Effetá, dat is: ga open.',
        35: 'En terstond werden zijn oren geopend, en de band van zijn tong werd losgemaakt, en hij sprak goed.',
        36: 'Hij verbood hun, het iemand te zeggen. Maar hoe strenger Hij het hun verbood, des te luider ze het vertelden.',
        37: 'Ze stonden ten hoogste verbaasd, en ze zeiden: Hij heeft alles wél gedaan; de doven doet Hij horen, en de stommen doet Hij spreken.',
    },
    8: {
        1: 'In die dagen, toen er weer een grote schare bijeen was, en deze niet te eten had, riep Hij zijn leerlingen, en zeide tot hen:',
        2: 'Ik heb medelijden met de schare; want reeds drie dagen zijn ze bij Mij, en ze hebben niets te eten.',
        3: 'Zo Ik ze hongerig naar huis laat gaan. zullen ze onderweg bezwijken; want sommigen van hen zijn van verre gekomen.',
        4: 'Zijn leerlingen antwoordden Hem: Hoe zou men ze hier, in een woestijn, genoeg brood kunnen geven?',
        5: 'Hij vroeg hun: Hoeveel broden hebt gij? Ze zeiden: Zeven.',
        6: 'Toen beval Hij de schare, zich neer te zetten op de grond. Hij nam de zeven broden, sprak een dankzegging uit, brak ze, en gaf ze aan zijn leerlingen, om ze hun aan te bieden. En ze reikten ze uit aan het volk.',
        7: 'Ook hadden ze enkele visjes; Hij sprak er de zegen over uit, en beval ook deze aan te bieden.',
        8: 'Ze aten, en werden verzadigd; en ze zamelden de overgeschoten brokken bijeen: zeven korven vol.',
        9: 'Er waren daar ongeveer vier duizend mannen. Toen liet Hij ze gaan.',
        10: 'Onmiddellijk daarna ging Hij met zijn leerlingen in de boot, en begaf Hij zich naar de streek van Dalmanoeta.',
        11: 'Nu kwamen de farizeën, en begonnen met Hem te twisten: ze eisten van Hem een teken uit de hemel, om Hem op de proef te stellen.',
        12: 'Hij zeide met een diepe zucht: Wat, eist dit geslacht een teken? Voorwaar, Ik zeg u: aan dit geslacht zal geen teken worden gegeven.',
        13: 'Hij verliet ze, ging weer de boot in, en voer naar de overzijde terug.',
        14: 'Maar ze hadden vergeten brood mee te nemen, zodat ze niet meer dan één brood bij zich aan boord hadden.',
        15: 'Toen vermaande Hij hen, en zeide: Let op, en wacht u voor het zuurdeeg der farizeën en voor het zuurdeeg van Herodes!',
        16: 'Ze redeneerden onder elkander, dat het was, omdat ze geen brood bij zich hadden.',
        17: 'Jesus merkte het, en sprak tot hen: Wat bespreekt gij toch met elkander; dat gij geen brood hebt? Hebt gij nu nog geen verstand of begrip? Is uw hart soms verstokt?',
        18: 'Gij hebt ogen, en toch ziet gij niet; oren, en toch hoort gij niet? Weet gij dan niet meer,',
        19: 'hoeveel korven vol brokken gij hebt verzameld, toen Ik de vijf broden brak voor vijf duizend man? Ze zeiden Hem: Twaalf.',
        20: 'En bij de zeven broden voor de vier duizend man, hoeveel manden met brokken hebt gij toen wel verzameld? Ze zeiden Hem: Zeven.',
        21: 'En Hij sprak tot hen: En nòg begrijpt gij het niet?',
        22: 'Zo kwamen ze te Betsáida aan. Daar bracht en een blinde naar Hem toe, en verzocht Hem, dien aan te raken.',
        23: 'Hij vatte den blinde bij de hand, en leidde hem buiten het dorp; Hij deed speeksel op zijn ogen, legde Hem de handen op, en vroeg hem: Ziet ge iets?',
        24: 'Hij begon te kijken, en sprak: Ik zie mensen: als bomen zie ik ze gaan.',
        25: 'Toen legde Hij opnieuw de handen op zijn ogen; en nu zag hij scherper. Hij was genezen, zodat hij alles duidelijk zag.',
        26: 'Hij zond hem naar huis, en zeide: Ga het dorp zelfs niet in.',
        27: 'Daarna ging Jesus met zijn leerlingen naar de dorpen van Cesarea Filippi. Onderweg ondervroeg Hij zijn leerlingen, en zeide tot hen: Wien zeggen de mensen, dat Ik ben?',
        28: 'Ze zeiden Hem: Johannes de Doper; anderen: Elias; anderen weer: één der profeten.',
        29: 'Nu vroeg Hij hun: Maar gij, wie zegt gij, dat Ik ben? Petrus antwoordde Hem: Gij zijt de Christus.',
        30: 'En Hij gebood hun ten strengste, hierover met niemand te spreken.',
        31: 'Toen begon Hij ze te onderrichten, dat de Mensenzoon veel zou moeten lijden, en verworpen moest worden door de oudsten, opperpriesters en schriftgeleerden; dat Hij moest worden gedood, en na drie dagen zou verrijzen.',
        32: 'Onbewimpeld sprak Hij er over. Petrus trok Hem ter zijde, en begon Hem tegen te spreken.',
        33: 'Maar Hij keerde zich om, zag zijn leerlingen aan, bestrafte Petrus, en sprak: Ga weg van Mij, satan! Want ge zijt niet bedacht op wat God wil, maar slechts op wat de mensen willen.',
        34: 'Nu riep Hij de schare met zijn leerlingen bijeen, en sprak tot hen: Zo iemand mijn volgeling wil zijn, dan moet hij zichzelf verloochenen, zijn kruis opnemen, en Mij volgen.',
        35: 'Want wie zijn leven wil redden, zal het verliezen; maar wie zijn leven verliest om Mij en om het Evangelie, zal het redden.',
        36: 'Wat baat het den mens, zo hij de hele wereld wint, maar schade lijdt aan zijn ziel?',
        37: 'Of wat zal een mens in ruil geven voor zijn ziel?',
        38: 'Want wie zich schaamt over Mij en mijn woorden bij dit overspelig en zondig geslacht, over hem zal zich ook de Mensenzoon schamen, als Hij in de heerlijkheid van zijn Vader komt, te zamen met de heilige engelen.',
        39: 'Nog sprak Hij tot hen: Voorwaar, Ik zeg u: Daar zijn er onder de hier aanwezigen, die de dood niet zullen smaken, voordat ze het koninkrijk Gods hebben zien komen in kracht.',
    },
    9: {
        1: 'Zes dagen later nam Jesus Petrus, Jakobus en Johannes met zich mee, en bracht ze heel afzonderlijk op een hoge berg. En Hij werd voor hun ogen van gedaante veranderd.',
        2: 'Zijn klederen werden blinkend en wit, zoals geen bleker op aarde ze wit kan maken.',
        3: 'Elias en Moses verschenen hun, en spraken met Jesus.',
        4: 'Toen nam Petrus het woord, en zei tot Jesus: Rabbi, het is ons goed, hier te zijn; laat ons drie tenten opslaan, één voor U, één voor Moses, en één voor Elias.',
        5: 'Hij wist niet goed wat hij zeide; want ze waren met schrik bevangen.',
        6: 'Nu kwam er een wolk, die hen overschaduwde, en uit de wolk klonk een stem: Deze is mijn geliefde Zoon, luistert naar Hem!',
        7: 'Op hetzelfde ogenblik keken ze rond, maar zagen niemand meer bij zich dan Jesus alleen.',
        8: 'En terwijl ze afdaalden van de berg, verbood Hij hun, aan iemand te vertellen wat ze hadden gezien, voordat de Mensenzoon van de doden was opgestaan.',
        9: 'Ze hielden zich aan dat woord. Toch vroegen ze onder elkander, wat het beduidde: op te staan van de doden.',
        10: 'Ze ondervroegen Hem dus: Waarom zeggen de farizeën en schriftgeleerden dan, dat eerst Elias komen moet?',
        11: 'Hij gaf hun ten antwoord: Zeker, Elias komt ook eerst, om alles te herstellen. Maar hoe staat er over den Mensenzoon geschreven? Dat Hij veel zal lijden en veracht zal worden.',
        12: 'En Ik zeg u: Elias is reeds gekomen; maar ze hebben met hem gedaan wat ze wilden, gelijk van hem geschreven staat.',
        13: 'Toen zij nu bij de andere leerlingen kwamen, zagen zij hen omringd van een talrijke schare, en van schriftgeleerden, die met hen twistten.',
        14: 'Zodra het volk Hem zag, liep het verbaasd naar Hem toe, om Hem te begroeten.',
        15: 'Hij vroeg hun: Waarom twist gij met hen?',
        16: 'Een uit de menigte antwoordde Hem: Meester, ik heb mijn zoon tot U gebracht, die van een stommen geest is bezeten.',
        17: 'Wanneer hij hem aangrijpt, dan werpt hij hem neer; dan schuimbekt hij, knarst met de tanden, en verstijft. Ik heb uw leerlingen verzocht, hem uit te drijven: maar ze konden het niet.',
        18: 'Hij antwoordde hun: O ongelovig geslacht, hoelang nog zal Ik bij u zijn, hoelang nog zal Ik u dulden? Brengt hem hier bij Mij!',
        19: 'Ze brachten hem. Zodra de geest Hem zag, deed hij den knaap de stuipen krijgen; hij viel op de grond, en wentelde zich schuimbekkend rond.',
        20: 'Hij vroeg aan zijn vader: Hoe lang heeft hij dit al, dat hem dit overkomt? Deze zeide: Van kindsbeen af;',
        21: 'dikwijls werpt hij hem in het vuur of in het water om hem te doden. Ach, indien het U mogelijk is, help ons dan, uit medelijden met ons.',
        22: 'Jesus sprak tot hem: Hoe; indien het U mogelijk is? Alles is mogelijk voor hem die gelooft.',
        23: 'Aanstonds riep de vader van den knaap onder tranen uit: Ik geloof; kom mijn ongeloof te hulp.',
        24: 'En daar Jesus zag, dat het volk tezamen liep, gebood Hij den onreinen geest, en zeide hem: Stomme en dove geest, Ik gebied u, ga van hem uit, en keer niet meer bij hem terug.',
        25: 'Schreeuwend en onder hevige stuiptrekkingen ging hij van hem uit; de knaap zag er uit als een lijk, zodat velen zeiden, dat hij gestorven was.',
        26: 'Maar Jesus vatte hem bij de hand, en richtte hem op; en hij stond overeind.',
        27: 'Toen Hij thuis was gekomen, vroegen zijn leerlingen Hem, terwijl zij alleen waren: Waarom konden wij hem niet uitdrijven?',
        28: 'Hij zei hun: Dit soort kan alleen met gebed worden uitgedreven.',
        29: 'Zij vertrokken vandaar, en reisden Galilea door. Maar Hij wilde niet, dat iemand het wist;',
        30: 'want Hij onderrichtte zijn leerlingen. Hij sprak tot hen: De Mensenzoon wordt overgeleverd in de handen der mensen; ze zullen Hem doden, maar na zijn dood zal Hij de derde dag verrijzen.',
        31: 'Ze begrepen dit niet: toch durfden ze Hem niet ondervragen.',
        32: 'Zij kwamen te Kafárnaum terug. En thuis gekomen, vroeg Hij hun: Waarover hebt gij onderweg gesproken?',
        33: 'Ze zwegen; want ze hadden onderweg met elkander getwist, wie de grootste zou zijn.',
        34: 'Hij zette Zich neer, riep de twaalf, en sprak tot hen: Zo iemand de eerste wil zijn, dan moet hij de laatste van allen zijn, en de dienaar van allen.',
        35: 'Nu nam Hij een kind, plaatste het in hun midden, omhelsde het, en zei hun:',
        36: 'Wie een van zulke kinderen opneemt in mijn Naam, hij neemt Mij op; en wie Mij opneemt, neemt Mij niet op, maar Hem die Mij gezonden heeft.',
        37: 'Johannes zeide tot Hem: Meester, we hebben iemand, die ons niet volgt, duivels zien uitdrijven in uw Naam; we hebben het hem verboden, omdat hij zich niet bij ons aansluit.',
        38: 'Maar Jesus sprak: Verbiedt het hem niet; want er is niemand, die een wonder verricht in mijn Naam, en onmiddellijk daarop Mij kan honen.',
        39: 'Wie niet tegen ons is, hij is voor ons.',
        40: 'En wie u een beker water te drinken geeft, juist omdat gij van Christus zijt, voorwaar Ik zeg u: Hij zal zijn loon niet missen.',
        41: 'Wie ergernis geeft aan een van deze kleinen, die in Mij geloven, het ware hem beter, dat hem een zware molensteen om de hals werd gehangen, en hij zo in de zee werd geworpen.',
        42: 'Zo uw hand u ergert, houw ze af. Het is beter, verminkt het Leven binnen te gaan, dan met twee handen naar de hel te gaan, naar het onuitblusbaar vuur,',
        44: 'En zo uw voet u ergert, houw hem af. Het is beter, kreupel het Leven binnen te gaan, dan met beide voeten in de hel te worden geworpen, in het onuitblusbaar vuur,',
        45: 'waar hun worm niet sterft, en het vuur niet gedoofd wordt.',
        46: 'En zo uw oog u ergert, ruk het uit. Het is beter met één enkel oog het koninkrijk Gods binnen te gaan, dan met twee ogen in de hel te worden geworpen,',
        47: 'waar hun worm niet sterft, en het vuur niet gedoofd wordt.',
        48: 'Allen moeten inderdaad met vuur worden gezouten.',
        49: 'Het zout is goed: als echter het zout smakeloos wordt, waar zult gij het dan mee zouten? Behoudt het zout in u, en leeft in vrede onder elkander.',
    },
    10: {
        1: 'Toen vertrok Hij vandaar, en ging naar het gebied van Judea en naar het Overjordaanse. En weer kwam er veel volk naar Hem toe, en onderwees Hij hen, zoals Hij gewoon was.',
        2: 'Ook de farizeën kwamen naar Hem toe, en vroegen, om Hem op de proef te stellen, of een man zijn vrouw mag verstoten. Hij gaf hun ten antwoord:',
        3: 'Wat heeft Moses u geboden?',
        4: 'Ze zeiden: Moses heeft toegestaan, een scheidingsbrief te schrijven, en haar zó te verstoten.',
        5: 'Jesus antwoordde hun: Om de hardheid van uw gemoed heeft Moses u deze wet gegeven;',
        6: 'maar van de aanvang der schepping af, heeft God hen man en vrouw gemaakt;',
        7: 'daarom zal de mens vader en moeder verlaten,',
        8: 'en de twee zullen één vlees zijn. Ze zijn dus geen twee meer, maar één vlees.',
        9: 'Wat dus God heeft verenigd, dat scheide geen mens.',
        10: 'Thuis ondervroegen zijn leerlingen Hem hierover opnieuw.',
        11: 'En Hij sprak tot hen: Wie zijn vrouw verstoot, en een andere huwt, begaat echtbreuk tegen haar.',
        12: 'En wanneer een vrouw haar man verlaat en een anderen huwt, begaat ze echtbreuk.',
        13: 'Nu bracht men kinderen naar Hem toe, opdat Hij ze zou aanraken. Maar de leerlingen wezen ze af.',
        14: 'Toen Jesus dit zag, werd Hij verstoord, en sprak Hij tot hen: Laat de kinderen tot Mij komen, en houdt ze niet tegen; want het koninkrijk Gods is voor hen, die zijn zoals zij.',
        15: 'Voorwaar, Ik zeg u: Wie het koninkrijk Gods niet aanneemt als een kind, zal er niet ingaan.',
        16: 'En Hij omhelsde ze, legde hun de handen op, en zegende hen.',
        17: 'En toen Hij Zich op weg begaf, kwam iemand toegelopen, knielde voor Hem neer, en vroeg Hem: Goede Meester, wat moet ik doen, om het eeuwige leven te verkrijgen?',
        18: 'Jesus sprak tot hem: Waarom noemt ge Mij goed? Niemand is goed, dan God alleen.',
        19: 'Ge kent de geboden: Gij zult niet doden; gij zult geen overspel doen; gij zult niet stelen; gij zult geen valse getuigenis geven; gij zult niemand te kort doen; eer uw vader en moeder.',
        20: 'Hij gaf hem ten antwoord: Meester, dit heb ik allemaal van mijn jeugd af onderhouden.',
        21: 'Toen zag Jesus hem teder aan, en sprak tot hem: Eén ding ontbreekt u nog. Ga heen, verkoop wat ge bezit, en geef het aan de armen; en ge zult een schat in de hemel bezitten. Kom dan, en volg Mij.',
        22: 'Maar hij werd ontstemd bij dat woord, en ging treurig heen; want hij had veel bezittingen.',
        23: 'Nu zag Jesus om Zich heen, en sprak tot zijn leerlingen: Hoe moeilijk toch zullen zij, die rijkdommen bezitten, het koninkrijk Gods binnengaan.',
        24: 'De leerlingen waren verbaasd over zijn woorden. Maar Jesus hernam, en zeide tot hen: Kinderen, hoe moeilijk is het toch, het koninkrijk Gods binnen te gaan!',
        25: 'Een kameel gaat makkelijker door het oog van een naald, dan een rijke in het koninkrijk Gods.',
        26: 'Toen waren ze nog meer ontsteld, en zeiden bij zichzelf: Wie kan dan zalig worden?',
        27: 'Jesus zag hen aan, en sprak: Bij de mensen is het onmogelijk, maar niet bij God; want bij God is alles mogelijk.',
        28: 'Nu nam Petrus het woord, en zei: Zie, wij hebben alles verlaten, en zijn U gevolgd.',
        29: 'Jesus sprak: Voorwaar, Ik zeg u: Er is niemand, die huis, broers of zusters, vader of moeder, kinderen of akkers om Mij en om het evangelie verlaat,',
        30: 'of hij zal ontvangen: nu in deze wereld, zij het ook te midden van vervolgingen, het honderdvoud van huizen, broers, zusters, moeders, kinderen en akkers; en in de toekomstige wereld het eeuwige leven.',
        31: 'Veel eersten zullen laatsten zijn, en laatsten zullen eersten zijn.',
        32: 'Zij waren nu op weg naar Jerusalem; Jesus ging voor hen uit, en zij volgden Hem, ontsteld en bevreesd. Hij nam de twaalf weer om Zich heen, en begon hun te zeggen, wat er met Hem zou gebeuren.',
        33: 'Ziet, wij gaan naar Jerusalem op, en de Mensenzoon zal worden overgeleverd aan de opperpriesters en schriftgeleerden; en ze zullen Hem ter dood veroordelen. Ze zullen Hem overleveren aan de heidenen;',
        34: 'men zal Hem bespotten, bespuwen, geselen en doden; maar na drie dagen zal Hij verrijzen.',
        35: 'Nu kwamen Jakobus en Johannes, de zonen van Zebedeüs, naar Hem toe, en zeiden: Meester, we wensen, dat Gij voor ons doet, wat we U willen vragen.',
        36: 'Hij zeide hun: Wat wenst gij, dat Ik voor u doe?',
        37: 'Ze zeiden: Verleen ons, dat wij in uw heerlijkheid mogen zitten, de één aan uw rechter-, de ander aan uw linkerhand.',
        38: 'Jesus sprak tot hen: Gij weet niet, wat gij vraagt. Kunt gij de kelk drinken, die Ik drink; of het doopsel ontvangen, waarmee Ik gedoopt word?',
        39: 'Ze zeiden Hem: Dat kunnen we. Jesus sprak tot hen: Gij zult wel de kelk drinken, die Ik drink, en het doopsel ontvangen, waarmee Ik gedoopt word;',
        40: 'maar zitten aan mijn rechter- of linkerhand kan Ik niet geven; dit is voor hem, wien het bereid is.',
        41: 'Toen de tien anderen dit hoorden, werden ze verontwaardigd op Jakobus en Johannes.',
        42: 'Maar Jesus riep hen naar Zich toe, en sprak tot hen: Gij weet, dat zij, die als vorsten worden beschouwd, over de volkeren heersen, en dat hun rijksgroten ze hun macht laten voelen.',
        43: 'Zó moet het niet zijn onder u; maar wie onder u groot wil worden, moet uw dienaar zijn;',
        44: 'en wie onder u de eerste wil zijn, moet aller dienstknecht wezen.',
        45: 'Ook de Mensenzoon is niet gekomen om gediend te worden, maar om te dienen, en zijn leven te geven tot losprijs voor velen.',
        46: 'Nu kwamen zij te Jericho aan. En toen Hij Jericho verliet, vergezeld van zijn leerlingen en een talrijke menigte, zat er een blinde bedelaar langs de weg: Bartimeüs, de zoon van Timeüs.',
        47: 'Zodra hij hoorde, dat het Jesus van Názaret was. begon hij hard te roepen: Jesus, Zoon van David, ontferm U mijner!',
        48: 'Velen vielen tegen hem uit, om hem tot zwijgen te brengen. Maar hij riep nog harder: Zoon van David, ontferm U mijner!',
        49: 'Jesus bleef staan, en sprak: Roept hem hier. Ze riepen den blinde, en zeiden tot hem: Houd moed, sta op; Hij roept u.',
        50: 'Hij wierp zijn mantel weg, sprong overeind, en ging naar Jesus toe.',
        51: 'Jesus sprak tot hem: Wat wilt ge, dat Ik voor u doe? De blinde zeide Hem: Rabboni, dat ik zien zal.',
        52: 'En Jesus sprak tot hem: Ga; uw geloof heeft u gered. En aanstonds zag hij weer, en volgde Hem op zijn weg.',
    },
    11: {
        1: 'Toen zij Jerusalem naderden, bij Bétfage en Betánië op de Olijfberg, zond Hij twee van zijn leerlingen vooruit,',
        2: 'en zei tot hen: Gaat naar het dorp, dat tegenover u ligt. Zodra ge daar binnenkomt, zult ge er een veulen vinden vastgebonden, waarop nog geen mens heeft gezeten; maakt het los, en brengt het hier.',
        3: 'Zo iemand u zegt: Wat doet ge daar? zegt dan: de Heer heeft het nodig, maar Hij stuurt het dadelijk hier terug.',
        4: 'Ze gingen heen, en vonden een veulen, vastgebonden voor de deur buiten op straat; en ze maakten het los.',
        5: 'Enige omstanders zeiden tot hen: Wat hebt ge dat veulen los te maken?',
        6: 'Ze antwoordden hun, zoals Jesus hun bevolen had; en men liet ze begaan',
        7: 'Ze brachten het veulen bij Jesus, en legden er hun mantels op; en Hij zette Zich daarop neer.',
        8: 'Nu spreidden velen hun mantels over de weg, en anderen de groene twijgen, die ze op de velden hadden gekapt.',
        9: 'En zij, die voorop gingen en volgden, riepen: Hosanna!',
        10: 'Gezegend die komt in de naam des Heren; Gezegend het rijk van onzen vader David, dat komt; Hosanna in den hogen!',
        11: 'Zo trok Hij Jerusalem en de tempel binnen. En toen Hij alles had afgezien, en het intussen laat was geworden, keerde Hij met de twaalf naar Betánië terug.',
        12: 'Toen zij de volgende dag uit Betánië vertrokken, kreeg Hij honger.',
        13: 'Van verre zag Hij een vijgeboom, die in het blad stond: Hij ging er heen, om te zien, of Hij er misschien iets aan kon vinden. Maar toen Hij er bij kwam, vond Hij er niets dan bladeren aan; want het was de tijd der vijgen niet.',
        14: 'En Hij sprak tot hem: Nooit in der eeuwigheid eet iemand nog vruchten van u! Zijn leerlingen hoorden het.',
        15: 'Zij kwamen in Jerusalem. Hij ging de tempel binnen, en begon er allen uit te drijven, die in de tempel verkochten en kochten; Hij smeet de tafels der wisselaars en de stoelen der duivenverkopers omver,',
        16: 'en liet niet toe, dat nog iemand koopwaar door de tempel droeg.',
        17: 'En Hij leerde aldus: Staat er niet geschreven: "Mijn huis zal heten een huis van gebed voor alle volkeren; maar gij hebt er een rovershol van gemaakt".',
        18: 'De opperpriesters en schriftgeleerden hoorden het, en zochten een middel om Hem te doden; want ze waren bang voor Hem, daar al het volk in bewondering stond voor zijn leer.',
        19: 'Tegen de avond verlieten ze de stad.',
        20: 'De volgende morgen kwamen zij langs de vijgeboom, en zagen, dat hij van de wortel af was verdord.',
        21: 'Petrus herinnerde zich het gebeurde, en sprak tot Hem: Rabbi, zie eens: de vijgeboom, die Gij gevloekt hebt, is verdord.',
        22: 'Jesus gaf hun ten antwoord: Hebt Godsgeloof!',
        23: 'Voorwaar, Ik zeg u: Zo iemand zegt tot deze berg: Hef u op, en werp u in zee; als hij niet twijfelt in zijn hart, maar gelooft, dat er gebeurt wat hij zegt, dan zal het gebeuren.',
        24: 'Daarom zeg Ik u: Zo gij iets vraagt in het gebed, gelooft dan, dat gij het verkrijgt; en gij zult het verkrijgen.',
        25: 'Maar wanneer gij staat te bidden, en gij iets tegen iemand hebt, vergeeft het dan: opdat uw Vader, die in de hemel is, ook u uw zonden vergeeft.',
        26: '(–)',
        27: 'Zo kwamen zij weer in Jerusalem terug. En terwijl Hij rondwandelde in de tempel, traden de opperpriesters, schriftgeleerden en oudsten op Hem toe,',
        28: 'en zeiden tot Hem: Met wat recht doet Gij dit alles; of wie heeft U het recht gegeven, om dit te doen?',
        29: 'Jesus sprak tot hen: Ook Ik zal U één vraag stellen; zo gij Mij daarop antwoordt, dan zal ook Ik u zeggen, met welk recht Ik dit alles doe.',
        30: 'Was het doopsel van Johannes van de hemel of van de mensen? Antwoordt Mij!',
        31: 'Ze overlegden bij zichzelf: Zo we zeggen: "van de hemel", dan zal Hij antwoorden: waarom hebt gij hem dan niet geloofd?',
        32: 'Zouden we zeggen: "van de mensen"? ….Maar ze waren bang voor het volk; want allen hielden Johannes voor een echten profeet.',
        33: 'Ze gaven dus Jesus ten antwoord: We weten het niet. Nu sprak Jesus tot hen: Dan zeg Ik u evenmin, met welk recht Ik dit alles doe.',
    },
    12: {
        1: 'Toen begon Hij tot hen in parabels te spreken: Een man plantte een wijngaard, omringde hem met een muur, groef er een wijnpers in, en bouwde er een toren op. Daarna verpachtte hij hem aan landbouwers, en vertrok naar het buitenland.',
        2: 'Op de vastgestelde tijd zond hij een knecht naar de landbouwers, om van de landbouwers zijn deel der vruchten van de wijngaard in ontvangst te nemen.',
        3: 'Maar ze grepen en sloegen hem, en zonden hem met lege handen heen.',
        4: 'Weer stuurde hij hun een anderen knecht; dien sloegen ze op het hoofd, en beledigden hem.',
        5: 'Nog eens stuurde hij een andere; en hem doodden ze. Zo nog verschillende anderen; den een sloegen ze, den ander doodden ze.',
        6: 'Nu had hij enkel nog zijn geliefden zoon. Ten laatste zond hij ook dezen tot hen, en sprak: Voor mijn zoon zullen ze wel ontzag hebben.',
        7: 'Maar die landbouwers zeiden tot elkander: Dat is de erfgenaam; komt, laten we hem doden, dan zullen wij de erfenis krijgen.',
        8: 'Ze grepen hem vast, doodden hem, en wierpen hem buiten de wijngaard.',
        9: 'Wat zal nu de heer van de wijngaard doen? Hij zal de landbouwers gaan verdelgen, en de wijngaard aan anderen geven.',
        10: 'Hebt gij dit Schriftwoord niet gelezen: De steen, die de bouwlieden hebben verworpen, Is de hoeksteen geworden;',
        11: 'De Heer heeft het gedaan: Een wonder is het in onze ogen.',
        12: 'Toen zochten ze zich van Hem meester te maken; maar ze vreesden het volk. Want ze begrepen, dat Hij met de parabel hen had bedoeld. Ze lieten Hem met rust, en gingen heen.',
        13: 'Daarop zonden ze enige farizeën en herodianen op Hem af, om Hem in zijn eigen woorden te verstrikken.',
        14: 'Ze kwamen, en zeiden tot Hem: Meester, we weten, dat Gij oprecht zijt, en niemand naar de ogen ziet; want Gij kent geen aanzien des persoons, maar leert naar waarheid de weg van God. Is het geoorloofd, den keizer belasting te betalen, of niet; moeten we betalen, of niet?',
        15: 'Maar Hij doorzag hun list, en sprak tot hen: Wat stelt gij Mij op de proef? Laat Mij eens een tienling zien.',
        16: 'Ze brachten er een. Hij zei hun: Wiens beeld en randschrift is dit? Ze zeiden Hem: Van den keizer.',
        17: 'Jesus sprak tot hen: Geeft dan den keizer, wat den keizer toekomt; en geeft aan God, wat God toekomt. En ze stonden verbaasd over Hem.',
        18: 'Ook de sadduceën, die de verrijzenis loochenen, kwamen op Hem af. Ze ondervroegen Hem:',
        19: 'Meester, Moses heeft ons voorgeschreven, dat, wanneer iemands broer komt te sterven en een vrouw zonder kinderen achterlaat, zijn broer dan de vrouw moet nemen, en nakomelingschap voor zijn broer moet verwekken.',
        20: 'Nu waren er zeven broers. De eerste nam een vrouw, en stierf zonder kinderen na te laten.',
        21: 'De tweede nam haar, en stierf; en ook deze liet geen kinderen na. Zo ook de derde,',
        22: 'en alle zeven, zonder kinderen na te laten. Het laatst van allen stierf de vrouw.',
        23: 'Wien van hen zal zij nu bij de verrijzenis, wanneer ze zullen opstaan, als vrouw toebehoren? Alle zeven hebben haar immers tot vrouw gehad.',
        24: 'Jesus sprak tot hen: Zoudt gij niet in dwaling zijn, omdat gij de Schriften niet kent, en evenmin de kracht van God?',
        25: 'Want wanneer men opstaat van de doden, dan huwt men niet, noch wordt men gehuwd, maar dan zal men zijn als engelen in de hemel.',
        26: 'En wat nu de verrijzenis der doden betreft, hebt gij in het boek van Moses bij het braambosverhaal niet gelezen, hoe God tot hem sprak: "Ik ben de God van Abraham, de God van Isaäk, de God van Jakob"?',
        27: 'Hij is toch geen God van doden, maar van levenden. Gij verkeert in grote dwaling.',
        28: 'Een der schriftgeleerden hoorde hun woordenwisseling, en kwam naderbij. Daar hij inzag, dat Hij hun goed had geantwoord, vroeg hij Hem: Wat is het allereerste gebod?',
        29: 'Jesus antwoordde hem: Het eerste is: Hoor Israël; de Heer, onze God, is de énige Heer;',
        30: 'gij zult den Heer uw God beminnen met heel uw hart, met heel uw ziel, met heel uw verstand en met heel uw kracht.',
        31: 'Het tweede is dit: Gij zult uw naaste beminnen als uzelf. Groter dan deze geboden is er geen.',
        32: 'De schriftgeleerde zeide Hem: Juist, Meester, Gij hebt naar waarheid gezegd, dat Hij één is, en dat er geen andere bestaat buiten Hem;',
        33: 'en dat Hem te beminnen met heel het hart en heel het verstand en met heel de kracht, en den naaste te beminnen als zichzelf, veel beter is dan alle brand- en slachtoffers.',
        34: 'Daar Jesus zag, dat hij verstandig geantwoord had, sprak Hij tot hem: Ge zijt niet ver van het koninkrijk Gods. Toen durfde niemand Hem meer ondervragen.',
        35: 'Nu nam Jesus het woord, en sprak bij zijn onderricht in de tempel: Hoe kunnen de schriftgeleerden zeggen, dat de Christus de zoon van David is?',
        36: 'David zelf heeft in den Heiligen Geest gezegd: "De Heer heeft gesproken tot mijn Heer: Zet U aan mijn rechterhand, Totdat Ik uw vijanden leg Als een voetbank voor uw voeten."',
        37: 'David zelf noemt Hem dus Heer; hoe is Hij dan zijn zoon? En de grote menigte luisterde graag naar Hem.',
        38: 'Nog sprak Hij bij zijn onderricht: Wacht u voor de schriftgeleerden, die er van houden, in lange gewaden rond te lopen, en op de markt te worden begroet;',
        39: 'die de eerste zetels begeren in de synagogen, en de eerste plaatsen aan de gastmalen;',
        40: 'die het goed der weduwen verslinden, en voor de schijn lange gebeden verrichten. Ze zullen des te strenger worden gevonnist.',
        41: 'En daar Hij tegenover de offerkist zat, zag Hij, hoe de menigte geld in de offerkist stortte. Een aantal rijken wierpen er veel in:',
        42: 'maar er kwam ook een arme weduwe, die er twee penningen, dat is een vierling, in deed.',
        43: 'Hij riep zijn leerlingen, en sprak tot hen: Voorwaar, Ik zeg u: Deze arme weduwe heeft meer in de offerkist gestort dan alle anderen.',
        44: 'Want allen hebben van hun overvloed geofferd, maar zij heeft van haar armoede alles gegeven, wat ze bezat, haar hele vermogen.',
    },
    13: {
        1: 'Toen Hij daarop de tempel verliet, zei een zijner leerlingen tot Hem: Zie, Meester, wat een stenen, en wat een gebouwen!',
        2: 'Jesus sprak tot hem: Ziet ge al die grote gebouwen? Er zal geen steen op de andere blijven, maar alles zal worden verwoest.',
        3: 'En toen Hij op de Olijfberg tegenover de tempel zat, ondervroegen Petrus, Jakobus, Johannes en Andreas Hem afzonderlijk:',
        4: 'Zeg ons: wanneer zal dat gebeuren; en wat zal het teken zijn, dat dit alles zal worden vervuld? Nu begon Jesus hun te zeggen:',
        5: 'Past op, dat niemand u misleidt!',
        6: 'Want velen zullen met mijn Naam optreden, en zeggen, dat Ik het ben; en ze zullen er velen misleiden.',
        7: 'En wanneer gij zult horen van oorlogen en oorlogsgeruchten, schrikt er niet van; want dit moet allemaal wel gebeuren, maar het is het einde nog niet.',
        8: 'Volk zal opstaan tegen volk, en rijk tegen rijk; en er zullen aardbevingen zijn en hongersnood, hier en elders. Maar dit alles is slechts het begin van de weeën.',
        9: 'Weest op uw hoede. Men zal u aan gerechtshoven overleveren, in synagogen zult gij worden gegeseld, en voor landvoogden en koningen zult gij terecht staan terwille van Mij, om getuigenis voor hen af te leggen.',
        10: 'Doch eerst moet aan alle volken het evangelie worden verkondigd.',
        11: 'En wanneer men u wegvoert en verraadt, weest dan niet bezorgd, wat gij zult zeggen; maar spreekt, wat u in dat uur zal worden ingegeven. Want niet gij zijt het, die spreekt, maar de Heilige Geest.',
        12: 'De broer zal zijn broer ter dood overleveren, en de vader zijn kind; de kinderen zullen opstaan tegen hun ouders, en ze doden.',
        13: 'En gij zult gehaat zijn bij allen om mijn naam; maar wie volhardt ten einde toe, zal zalig worden.',
        14: 'Wanneer gij de gruwel der ontheiliging ziet staan, waar hij niet staan mag, —die het leest, begrijpe het! —laten zij, die in Judea zijn, dan naar de bergen vluchten;',
        15: 'en wie op het dakterras is, dale niet af in het huis, en ga niet naar binnen, om iets mee te nemen uit zijn huis;',
        16: 'en wie op het veld is, kere niet terug, om zijn kleed te gaan halen.',
        17: 'Wee in die dagen de zwangere en zogende vrouwen!',
        18: 'Bidt toch, dat het niet in de winter gebeurt.',
        19: 'Want dat zullen dagen zijn van ellende, zoals er nooit is geweest van het begin der wereld af, die God heeft geschapen, tot heden toe, en zoals er ook nooit meer zal zijn.',
        20: 'En zo de Heer die dagen niet had verkort, geen mens bleef behouden; maar om de uitverkorenen, die Hij Zich heeft gekozen, heeft Hij die dagen verkort.',
        21: 'Als dan iemand u zegt: Zie, hier is de Christus; zie, Hij is ginds; gelooft het niet.',
        22: 'Want er zal menig valse-christus opstaan en tal van valse profeten, en ze zullen tekenen en wonderen verrichten; zodat als ‘t mogelijk was, ze zelfs de uitverkorenen zouden misleiden.',
        23: 'Weest op uw hoede! Ziet, Ik heb u alles voorspeld.',
        24: 'Maar in die dagen, na die ellende, zal de zon worden verduisterd, en de maan geen licht meer geven:',
        25: 'de sterren zullen van de hemel vallen, en de krachten der hemelen zullen worden geschokt.',
        26: 'Dan zal men den Mensenzoon op de wolken zien komen met grote macht en majesteit.',
        27: 'Dan zal Hij zijn engelen zenden, en Hij zal van de vier windstreken zijn uitverkorenen verzamelen, van het einde der aarde tot aan het einde des hemels.',
        28: 'Leert van de vijgeboom deze gelijkenis. Wanneer zijn twijg al zacht is geworden, en de bladeren al ontspruiten, dan weet gij, dat de zomer nabij is.',
        29: 'Zo ook, wanneer gij dit alles gebeuren ziet, weet dan, dat het dicht voor de deur staat.',
        30: 'Voorwaar, Ik zeg u: dit geslacht gaat niet voorbij, eer dit alles is geschied.',
        31: 'Hemel en aarde zullen voorbijgaan, maar mijn woorden zullen niet voorbijgaan.',
        32: 'Maar van die dag of dat uur weet niemand iets af, zelfs niet de engelen in de hemel, noch de Zoon, maar de Vader alleen.',
        33: 'Weest op uw hoede en waakt! Want gij weet niet, wanneer de tijd daar is.',
        34: 'Het gaat er mee, als met een mens, die naar het buitenland reisde, zijn huis verliet, en het beheer aan zijn dienaars overdroeg; aan ieder gaf hij zijn taak, en aan den deurwachter beval hij te waken.',
        35: 'Waakt dus, want gij weet niet, wanneer de heer des huizes komt: ‘s avonds laat of te middernacht, bij het hanengekraai of ‘s morgens vroeg.',
        36: 'Hij komt onverwacht; moge hij u niet slapend vinden.',
        37: 'Wat Ik ú zeg, dat zeg Ik aan allen: Waakt!',
    },
    14: {
        1: 'Twee dagen later was het Pasen, en het feest van de ongedesemde broden. En de opperpriesters en schriftgeleerden zochten naar een middel, om Hem met list gevangen te nemen, en te doden.',
        2: 'Ze zeiden: Niet op het feest; er mocht eens oproer komen onder het volk.',
        3: 'Terwijl Hij nu te Betánië was in het huis van Simon den melaatse, en aanlag aan tafel, kwam er een vrouw, die een albasten kruik vol echte, kostbare nardus droeg; ze brak de kruik stuk, en goot de nardus uit over zijn hoofd.',
        4: 'Sommigen werden er verontwaardigd over, en zeiden: Waarom die verkwisting met de balsem?',
        5: 'Want deze balsem had voor meer dan driehonderd tienlingen verkocht kunnen worden, en aan de armen worden gegeven. En ze waren boos op haar.',
        6: 'Maar Jesus sprak: Laat haar met rust! Waarom valt gij haar lastig? Ze heeft een goed werk aan Mij gedaan.',
        7: 'Want de armen hebt gij altijd bij u, en gij kunt hun goed doen, wanneer gij wilt; Mij niet.',
        8: 'Zij heeft gedaan, wat ze kon; ze heeft reeds vooruit mijn lichaam gebalsemd voor de begrafenis.',
        9: 'Voorwaar, Ik zeg u: Overal, in heel de wereld, waar dit evangelie wordt gepreekt, zal ook tot hare gedachtenis worden vermeld, wat ze gedaan heeft.',
        10: 'Toen ging Judas Iskáriot, een van de twaalf, naar de opperpriesters, om Hem aan hen over te leveren.',
        11: 'Ze verheugden zich, toen ze dit hoorden, en beloofden hem, geld te geven. Hij zocht dus naar een gelegenheid, om Hem te verraden.',
        12: 'Op de eerste dag der ongedesemde broden, waarop men het Pascha offerde, zeiden zijn leerlingen tot Hem: Waar wilt Gij, dat we U de toebereidselen gaan maken, om het paasmaal te eten?',
        13: 'Hij zond dus twee van zijn leerlingen heen, en zei hun: Gaat naar de stad; daar zult gij een man tegenkomen, die een kruik water draagt; gaat hem achterna.',
        14: 'en zegt, waar hij binnengaat, tot den heer des huizes: De Meester zegt: waar is de zaal, waar Ik met mijn leerlingen het paasmaal kan houden?',
        15: 'En Hij zal u een grote opperzaal aanwijzen, goed gemeubeld en van alles voorzien; maakt daar alles voor ons gereed.',
        16: 'De leerlingen gingen heen, kwamen in de stad, en vonden het, zoals Hij hun had gezegd; en ze maakten het paasmaal gereed.',
        17: 'Tegen de avond kwam Hij met het twaalftal.',
        18: 'En terwijl ze aanlagen en aten, sprak Jesus: Voorwaar, Ik zeg u: één van u zal Mij verraden, een die met Mij eet.',
        19: 'Nu werden ze bedroefd, en vroegen Hem de een na den ander: Ben ik het?',
        20: 'Hij sprak tot hen: Eén uit de twaalf, die met Mij in de schotel doopt.',
        21: 'De Mensenzoon gaat wel heen, zoals van Hem geschreven staat; maar wee dien mens, door wien de Mensenzoon verraden wordt. Het zou beter voor hem zijn, zo hij niet was geboren, die mens.',
        22: 'Terwijl zij nu aten, nam Jesus brood, zegende het, brak het, gaf het hun, en zeide: Neemt, dit is mijn lichaam.',
        23: 'Daarna nam Hij de kelk, sprak een dankgebed uit, en gaf hun de kelk; en zij dronken er allen uit.',
        24: 'En Hij zeide tot hen: Dit is mijn bloed van het Verbond, dat voor velen wordt vergoten.',
        25: 'Voorwaar, Ik zeg u: Ik zal de vrucht van de wijnstok niet meer drinken tot op de dag, waarop Ik ze hernieuwd zal drinken in het koninkrijk Gods.',
        26: 'En nadat zij de lofzang hadden gezongen, gingen zij naar de Olijfberg.',
        27: 'Toen sprak Jesus tot hen: Deze nacht zult gij allen aan Mij worden geërgerd. Want er staat geschreven: "Ik zal den herder slaan. en de schapen zullen worden verstrooid."',
        28: 'Maar wanneer Ik verrezen zal zijn, zal Ik u voorgaan naar Galilea.',
        29: 'Petrus zei Hem: Al werden ook allen aan U geërgerd, ik niet.',
        30: 'Jesus sprak tot hem: Voorwaar, Ik zeg u: Heden nog in deze nacht, eer de haan twee maal gekraaid heeft, zult ge Mij driemaal verloochenen.',
        31: 'Maar nog krachtiger zeide hij: Al moest ik zelfs met U sterven, verloochenen zal ik U niet. Zo spraken ook allen.',
        32: 'Toen kwamen zij aan een landgoed, Getsémani genaamd. Nu zei Hij tot zijn leerlingen: Zet u hier neer, terwijl Ik ga bidden.',
        33: 'Hij nam Petrus, Jakobus en Johannes met Zich mee, en begon ontroerd en angstig te worden.',
        34: 'En Hij sprak tot hen: Mijn ziel is dodelijk bedroefd: blijft hier en waakt.',
        35: 'Hij ging nog een weinig verder, viel neer ter aarde, en bad, dat dit uur, zo het mogelijk was, Hem mocht voorbijgaan.',
        36: 'Hij sprak: Abba, Vader; alles is mogelijk bij U; neem deze kelk van Mij weg. Maar niet wat Ik wil, maar wat Gij wilt.',
        37: 'Nu ging Hij terug, en vond hen in slaap. Hij sprak tot Petrus: Simon, slaapt ge? Kunt ge dan niet één uur waken?',
        38: 'Waakt en bidt, opdat gij niet in bekoring komt. De geest is gewillig, maar het vlees is zwak.',
        39: 'En weer ging Hij heen, en bad met dezelfde woorden.',
        40: 'Hij keerde terug, en vond hen opnieuw in slaap; want hun ogen vielen toe. Ze wisten niet, wat ze Hem zouden antwoorden.',
        41: 'Toen kwam Hij voor de derde maal, en sprak tot hen: Slaapt nu voort, en rust uit. Het is beslist. Het uur is gekomen: ziet, de Mensenzoon wordt overgeleverd in de handen der zondaars.',
        42: 'Staat op, laat ons gaan; ziet, die Mij verraadt is nabij.',
        43: 'En terwijl Hij nog sprak, kwam Judas, een van de twaalf, vergezeld van een bende met zwaarden en stokken, uitgezonden door de opperpriesters, schriftgeleerden en oudsten.',
        44: 'De verrader had hun een teken gegeven, en gezegd: Dien Ik zal kussen. Hij is het; grijpt Hem vast, en leidt Hem weg onder strenge bewaking.',
        45: 'Hij kwam dus, liep terstond op Hem toe, en zeide: Rabbi. En hij kuste Hem.',
        46: 'Toen sloegen ze de hand aan Hem, en grepen Hem vast.',
        47: 'Maar een der aanwezigen trok het zwaard, trof den knecht van den hogepriester, en sloeg hem het oor af.',
        48: 'Nu nam Jesus het woord, en sprak tot hen: Gij zijt uitgetrokken als tegen een rover, met zwaarden en stokken, om Mij gevangen te nemen.',
        49: 'Dag aan dag leerde Ik bij u in de tempel, en gij hebt Mij niet gegrepen. Maar zo moeten de Schriften worden vervuld.',
        50: 'Toen verlieten Hem allen, en namen de vlucht.',
        51: 'Maar een jonge man, met slechts een nachtkleed om het lijf, ging Hem achterna. Ze grepen hem vast;',
        52: 'maar hij liet het nachtkleed in de steek, en vluchtte weg, ongekleed.',
        53: 'Ze brachten Jesus bij den hogepriester; en alle opperpriesters, oudsten en schriftgeleerden kwamen bijeen.',
        54: 'Petrus volgde Hem van verre tot in de voorhof van den hogepriester; hij zette zich bij de dienstknechten neer, om zich bij het vuur te warmen.',
        55: 'De opperpriesters en heel de Hoge Raad zochten nu naar een aanklacht tegen Jesus, om Hem ter dood te brengen. Maar ze vonden niets.',
        56: 'Wel brachten velen valse beschuldigingen tegen Hem in, maar de getuigenissen stemden niet overeen.',
        57: 'Toen traden er enigen naar voren, die vals tegen Hem getuigden, en zeiden:',
        58: 'We hebben Hem horen zeggen: Ik zal deze tempel afbreken, die door mensenhanden is gemaakt, en in drie dagen een andere bouwen, die niet door mensenhanden gemaakt is.',
        59: 'Maar ook hier stemde hun getuigenis niet overeen.',
        60: 'Toen stond de hogepriester op in de kring, en ondervroeg Jesus, aldus: Antwoordt Gij niets? Wat getuigen dezen tegen U?',
        61: 'Maar Hij zweeg, en antwoordde niets. Opnieuw vroeg Hem de hogepriester, en zei Hem: Zijt Gij de Christus, de Zoon van den Gezegende?',
        62: 'Jesus sprak: Ik ben het! Gij zult den Mensenzoon gezeten zien aan de rechterhand der Majesteit, en Hem zien komen op de wolken des hemels.',
        63: 'Toen scheurde de hogepriester zijn klederen, en zeide: Wat hebben we nog getuigen nodig?',
        64: 'Gij hebt de godslastering gehoord. Wat dunkt u? En allen spraken het vonnis uit, dat Hij des doods schuldig was.',
        65: 'Toen begonnen sommigen Hem te bespuwen, zijn gelaat te bedekken en Hem kaakslagen te geven, en dan tot Hem te zeggen: Profeteer! Ook de dienstknechten sloegen Hem in het gelaat.',
        66: 'Terwijl Petrus zich dus beneden in de voorhof bevond, kwam daar een der dienstmeisjes van den hogepriester;',
        67: 'en toen ze Petrus zich zag warmen, keek ze hem aan, en sprak: Ook gij waart bij Jesus van Názaret.',
        68: 'Doch hij loochende het en sprak: Ik weet niet, ik begrijp niet, wat ge zegt. Hij ging weg naar de voorhal; en er kraaide een haan.',
        69: 'Maar het dienstmeisje, dat hem had opgemerkt, begon nu weer tot de omstanders te zeggen: Hij is er een van.',
        70: 'Maar hij loochende het opnieuw. Kort daarop zeiden ook de omstanders op hun beurt tot Petrus: Zeker, ook gij zijt er een van, want ge zijt een Galileër.',
        71: 'Nu begon hij te vloeken en te zweren: Ik ken den mens niet, van wien gij spreekt.',
        72: 'En aanstonds kraaide een haan voor de tweede maal. Toen dacht Petrus aan het woord, dat Jesus tot hem gesproken had: Eer de haan tweemaal gekraaid heeft, zult ge Mij driemaal verloochenen. En hij barstte in tranen los.',
    },
    15: {
        1: 'Heel in de vroegte namen de opperpriesters met de oudsten, schriftgeleerden en heel de Hoge Raad een beslissing. Ze lieten Jesus binden, voerden Hem weg, en leverden Hem over aan Pilatus.',
        2: 'Pilatus ondervroeg Hem: Zijt Gij de Koning der Joden? Hij gaf hem ten antwoord: Ge zegt het.',
        3: 'Nu brachten de opperpriesters vele beschuldigingen tegen Hem in.',
        4: 'Pilatus vroeg Hem opnieuw: Antwoordt Gij niets? Zie, wat zware beschuldiging ze tegen U inbrengen.',
        5: 'Jesus gaf geen antwoord meer, zodat het Pilatus verbaasde.',
        6: 'Maar op de feestdagen liet hij hun, naar eigen keuze, een der gevangenen vrij.',
        7: 'Nu zat er een zekere Barabbas gevangen tegelijk met andere oproermakers, die bij het oproer een moord hadden begaan.',
        8: 'Toen het volk dan kwam opdagen, en aan Pilatus begon te vragen, wat hij hun gewoonlijk toestond.',
        9: 'antwoordde hij hun: Wilt gij, dat ik u den Koning der Joden vrijlaat?',
        10: 'Want hij begreep, dat de opperpriesters Hem uit afgunst hadden overgeleverd.',
        11: 'Maar de opperpriesters hitsten de menigte op: hij moest hun maar liever Barabbas vrijlaten.',
        12: 'Pilatus hernam, en sprak tot hen: Wat moet ik dan met Hem doen, dien gij Koning der Joden noemt?',
        13: 'En ze schreeuwden opnieuw: Kruisig Hem!',
        14: 'Pilatus zei hun: Wat heeft Hij dan voor kwaad gedaan? Maar ze schreeuwden nog harder: Kruisig Hem!',
        15: 'Toen liet Pilatus hun Barabbas vrij, om het volk terwille te zijn: maar Jesus liet hij geselen, en gaf Hem over, om te worden gekruisigd.',
        16: 'Nu brachten de soldaten Hem naar binnen, in de voorhof van het rechthuis, en riepen de hele bende bijeen.',
        17: 'Ze hingen Hem het purper om, en vlochten een doornenkroon, en zetten die op zijn hoofd.',
        18: 'Toen gingen ze Hem huldigen: Wees gegroet, Koning der Joden!',
        19: 'Dan sloegen ze Hem met een rietstok op het hoofd, bespuwden Hem, wierpen zich op de knieën, en brachten Hem hulde.',
        20: 'En nadat ze Hem hadden bespot, deden ze Hem het purper af, trokken Hem zijn klederen aan, en voerden Hem weg ter kruisiging.',
        21: 'Ze dwongen een voorbijganger, die juist van het veld kwam, zijn kruis te dragen; het was Simon van Cyrene, de vader van Alexander en Rufus.',
        22: 'Ze voerden Hem naar een plaats, die Gólgota of schedelplaats heet.',
        23: 'Nu gaven ze Hem wijn te drinken met mirre vermengd; maar Hij nam er niet van.',
        24: 'Na Hem gekruisigd te hebben, verdeelden ze zijn klederen, en wierpen het lot over hun aandeel.',
        25: 'Het was het derde uur, toen ze Hem kruisigden.',
        26: 'Het opschrift met de reden van zijn veroordeling luidde: De Koning der Joden!',
        27: 'Met Hem kruisigden ze twee rovers, één aan zijn rechterhand, en één aan zijn linker.',
        28: 'Toen werd de Schrift vervuld, die zegt: "En onder de booswichten werd Hij gerekend."',
        29: 'En zij die voorbijgingen, lasterden Hem, schudden het hoofd, en zeiden: Ba! Gij, die de tempel afbreekt en in drie dagen weer opbouwt,',
        30: 'red Uzelf, kom af van het kruis!',
        31: 'Zo spotten ook de opperpriesters en schriftgeleerden onder elkander, en zeiden: Anderen heeft Hij gered, Zichzelf kan Hij niet redden;',
        32: 'de Christus, Israëls Koning, kome nu eens af van het kruis, opdat we het zien en geloven! Zelfs zij beschimpten Hem, die met Hem waren gekruisigd.',
        33: 'Tegen het zesde uur tot het negende toe, viel er duisternis neer over het hele land.',
        34: 'Omstreeks het negende uur riep Jesus met luider stem: Eloi Eloi, lamma sabaktáni; dat is: "Mijn God, mijn God, waarom verlaat Gij Mij!"',
        35: 'Sommigen, die daar stonden, hoorden het en zeiden: Zie, Hij roept Elias.',
        36: 'Eén hunner liep heen, vulde een spons met azijn, stak ze op een riet, gaf Hem te drinken, en zeide: Wacht, laat ons eens zien, of Elias Hem er soms af komt halen.',
        37: 'Toen riep Jesus met luider stem, en gaf de geest.',
        38: 'En het voorhangsel van de tempel scheurde in tweeën van boven tot onder.',
        39: 'Toen nu de hoofdman, die tegenover Hem post had gevat, zag, dat Hij onder zulke omstandigheden gestorven was, sprak hij: Waarachtig, deze man was Gods Zoon.',
        40: 'Ook enige vrouwen stonden van verre toe te zien; onder anderen, Maria Magdalena, Maria de moeder van Jakobus den Jongeren en van Josef en Salome;',
        41: 'ze waren Hem gevolgd, toen Hij in Galilea was, om Hem te dienen; ook vele anderen waren er bij, die met Hem naar Jerusalem waren opgegaan.',
        42: 'Daar het een dag van voorbereiding was, daags voor de sabbat, en het reeds tegen de avond liep,',
        43: 'kwam Josef van Arimatea, een voornaam raadsheer, die ook zelf het koninkrijk Gods verwachtte, en ging vrijmoedig naar Pilatus, om hem het lichaam van Jesus te vragen.',
        44: 'Pilatus verwonderde zich, dat Hij reeds gestorven was; hij ontbood den hoofdman, en vroeg hem, of Hij al lang was gestorven.',
        45: 'En toen hij dit van den hoofdman vernomen had, stond hij het lichaam aan Josef af.',
        46: 'Nu kocht deze een lijnwaad, nam Hem af van het kruis, en wikkelde Hem in het lijnwaad. En hij legde Hem in een graf, dat in een rots was uitgehouwen, en rolde een steen voor de ingang van het graf.',
        47: 'Maria Magdalena en Maria van Josef zagen toe, waar Hij werd neergelegd.',
    },
    16: {
        1: 'Toen de sabbat voorbij was, kochten Maria Magdalena, Maria van Jakobus, en Salome specerijen, om Jesus te gaan balsemen.',
        2: 'Zeer vroeg op de eerste dag der week, bij het opgaan der zon, kwamen ze bij het graf.',
        3: 'En ze zeiden tot elkander: Wie zal ons de steen wegrollen voor de ingang van het graf?',
        4: 'Maar toen ze gingen zien, merkten ze, dat de steen al op zij was gerold; want hij was zeer groot.',
        5: 'Ze gingen het graf in, en zagen aan de rechterkant een jongeling zitten, in een wit gewaad gekleed. Ze werden hevig ontsteld.',
        6: 'Maar hij sprak tot haar: Weest maar niet bang! Gij zoekt Jesus van Názaret, die gekruisigd is? Hij is verrezen; hier is Hij niet. Ziet hier de plaats, waar men Hem heeft neergelegd.',
        7: 'Gaat nu heen, en zegt aan zijn leerlingen en aan Petrus: Hij gaat u vóór naar Galilea; daar zult gij Hem zien, zoals Hij het u heeft gezegd.',
        8: 'Ze gingen naar buiten, en vluchtten weg van het graf; want schrik en ontzetting had haar bevangen. En ze zeiden er niemand iets van; zo bang waren ze.',
        9: 'Toen Hij dan verrezen was, ‘s morgens vroeg, op de eerste dag van de week, verscheen Hij het eerst aan Maria Magdalena, uit wie Hij zeven duivels had uitgedreven.',
        10: 'Deze ging het melden aan hen, die met Hem waren geweest, en die nu treurden en weenden.',
        11: 'Maar toen ze hoorden, dat Hij leefde en door haar was gezien, geloofden ze het niet.',
        12: 'Daarna verscheen Hij in een andere gedaante aan twee van hen, die op weg waren naar buiten.',
        13: 'Deze gingen terug, en meldden het aan de anderen; maar ook hen geloofden ze niet.',
        14: 'Eindelijk verscheen Hij aan alle elf, terwijl ze aan tafel waren. Hij verweet hun het ongeloof en de verstoktheid van hart, omdat ze hèn niet hadden geloofd, die Hem na de verrijzenis hadden gezien.',
        15: 'En Hij sprak tot hen: Gaat heel de wereld door, en predikt het evangelie aan ieder schepsel.',
        16: 'Wie gelooft en gedoopt is, zal zalig worden; maar wie niet gelooft, zal worden veroordeeld.',
        17: 'Deze wonderen zullen hen vergezellen, die hebben geloofd: in mijn Naam zullen ze duivels uitdrijven; vreemde talen zullen ze spreken;',
        18: 'slangen zullen ze opnemen; en al drinken ze dodelijk vergif, het zal hun niet schaden; zieken zullen ze de handen opleggen, en zij zullen genezen.',
        19: 'Toen de Heer Jesus met hen gesproken had, is Hij opgenomen ten hemel, en is neergezeten aan de rechterhand Gods.',
        20: 'Maar zij trokken uit, om overal te preken; en de Heer werkte met hen mee, en bevestigde het woord door de wonderen, die het vergezelden.',
    },
}
